function heroCover(item, index) { const poster = posterOf(item); return `<div class="swiper-slide" data-cover-index="${index}"><button class="hero-cover" data-open="${item.type}:${item.id}" aria-label="Open ${escapeHTML(titleOf(item))}"><img class="cover-poster" src="${poster}" alt="" loading="eager"><span>${escapeHTML(titleOf(item))}</span></button></div>`; }
function heroCoverflow() { const covers = state.featuredPool.length ? [...state.featuredPool, ...state.featuredPool, ...state.featuredPool] : []; return covers.length ? `<div class="swiper seven-coverflow" aria-label="Featured titles"><div class="swiper-wrapper">${covers.map((item, index) => heroCover(item, index % state.featuredPool.length)).join("")}</div></div>` : ""; }
