function bindCommon() { document.querySelectorAll("[data-home]").forEach(button => button.onclick = () => { state.route = "home"; render(); }); document.querySelectorAll("[data-open]").forEach(button => button.onclick = () => { const [type, id] = button.dataset.open.split(":"); openItem(type, id); }); document.querySelectorAll("[data-person]").forEach(button => button.onclick = () => openPerson(button.dataset.person)); document.querySelectorAll("[data-continue]").forEach(button => button.onclick = () => { const [type, id, season, episode] = button.dataset.continue.split(":"), item = { type, id:Number(id), season:Number(season) || undefined, episode:Number(episode) || undefined }, saved = JSON.parse(localStorage.getItem(watchKey(item)) || "{}"); state.player = { ...item, title:saved.title, overview:"", posterPath:saved.posterPath, genreIds:saved.genreIds || [], startAt:savedStart(item) }; state.route = "player"; render(); }); document.querySelectorAll("[data-explore]").forEach(button => button.onclick = () => { const view = state.explorable?.[button.dataset.explore]; if (!view) return; state.exploreView = view; state.route = "explore"; render(); }); const input = document.querySelector("#search"); let timer; input.oninput = () => { clearTimeout(timer); timer = setTimeout(() => suggestSearch(input), 350); }; input.onkeydown = event => { if (event.key === "Enter") { event.preventDefault(); searchRequest++; hideSearchSuggestions(input); search(input.value); } }; input.onblur = () => setTimeout(() => hideSearchSuggestions(input), 160); input.onfocus = () => { if (input.value.trim().length >= 2 && state.searchResults?.length) showSearchSuggestions(input, input.value.trim(), state.searchResults); }; document.querySelectorAll("[data-search-focus]").forEach(button => button.onclick = () => input.focus()); document.querySelectorAll("[data-for-you]").forEach(button => button.onclick = openForYou); document.querySelectorAll("[data-movies]").forEach(button => button.onclick = () => openCatalog("movie")); document.querySelectorAll("[data-shows]").forEach(button => button.onclick = () => openCatalog("tv")); document.querySelectorAll("[data-auth]").forEach(button => button.onclick = () => showAuth()); document.querySelectorAll("[data-account]").forEach(button => button.onclick = showAccount); }
window.addEventListener("message", event => { let payload; try { payload = typeof event.data === "string" ? JSON.parse(event.data) : event.data; } catch { return; } if (state.route !== "player" || payload?.type !== "PLAYER_EVENT") return; const data = payload.data || {}, duration = Number(data.duration) || 0, currentTime = Number(data.currentTime) || 0; if (!duration) return; const progress = Math.min(100, currentTime / duration * 100); localStorage.setItem(watchKey(state.player), JSON.stringify({currentTime,duration,progress,watched:progress >= 90,genreIds:state.player.genreIds || [],type:state.player.type,id:state.player.id,season:state.player.season || null,episode:state.player.episode || null,title:state.player.title,posterPath:state.player.posterPath || null,lastWatchedAt:new Date().toISOString()})); queueProgressSync(state.player, currentTime, duration, progress); const bar = document.querySelector("#bar"), time = document.querySelector("#time"); if (bar) bar.style.width = `${progress}%`; if (time) time.textContent = `${Math.floor(currentTime)}s of ${Math.floor(duration)}s`; });
if ("serviceWorker" in navigator) navigator.serviceWorker.register("/service-worker.js");
boot();
